from typing import BinaryIO


class Device:
    def __init__(self, sink: BinaryIO):
        self.sink = sink

    def play(self, buffer: bytearray) -> None:
        self.sink.write(buffer)


def _fill_output(buffer: bytearray, source: BinaryIO) -> None:
    # Set each output byte to zero.
    # The device writes the whole reused buffer after a short read; clear it
    # so bytes left over from the previous read do not play again.
    buffer[:] = b"\x00" * len(buffer)
    source.readinto(buffer)


def play_chunks(source: BinaryIO, device: Device, count: int) -> None:
    buffer = bytearray(4096)
    for _ in range(count):
        _fill_output(buffer, source)
        device.play(buffer)
